 const tabs=[[`/${v}/`,'home',labels[v],'home'],[listPath(),'bed',v==='resort'?'الأكواخ':v==='stay'?'القسمان':'التفاصيل','stays'],[servicesPath(),'services','الخدمات','services'],[`/${v}/contact/`,'info','المعلومات','info']];
