 return `<div class="venue-overview resort-overview venue-guide-overview"><section class="resort-intro"><h1>دليلكم ل${safe(venue().name)}</h1><p><span>${intro[0]}</span><br><span>${intro[1]}</span></p></section><section class="hero"><img src="${stay?u.images[0]:'/imgs/chalet_1.webp'}" alt="${safe(venue().name)}" fetchpriority="high"><div class="hero-content"><span class="eyebrow">${icon('pin')}${safe(venue().location)}</span><h2>${safe(venue().name)}</h2><p>خصوصية تليق بكم وراحة تستحقونها</p></div></section><div class="facts-strip">${facts.map(([i,t])=>`<div>${icon(i)}<span>${safe(t)}</span></div>`).join('')}</div>${stay?'<p class="venue-footnote">يمكن حجز قسم واحد أو القسمين معًا</p>':''}</div>`;
