 return `<article class="unit-card resort-unit-card stay-unit-card" data-unit-id="${u.id}"><a class="card-photo" href="${prefix(u.path)}" aria-label="التفاصيل والصور — ${safe(u.name)}"><img src="${safe(u.images[0])}" alt="${safe(u.name)}" loading="lazy"></a><div class="card-copy"><div class="card-title-row stay-card-title"><h3>${safe(u.name)}</h3><span class="card-audience">${safe(u.suitable)}</span></div><div class="card-facts"><span>${icon('users')}${guests(u.guests)}</span><span>${icon('bed')}${rooms(u.rooms)}</span></div>${feature?`<p class="stay-card-feature">${safe(feature)}</p>`:''}<div class="card-actions stay-card-actions">${link(u.path,'التفاصيل والصور','button primary card-details')}</div></div></article>`;
