function gallery(u){return `<div class="gallery"><button class="gallery-photo" data-lightbox-unit="${u.id}" aria-label="تكبير الصورة"><img id="gallery-image" src="${safe(u.images[photoIndex])}" alt="${safe(u.labels[photoIndex]||u.name)}" fetchpriority="high"></button><button class="gallery-control previous" data-photo="-1" aria-label="الصورة السابقة">${icon('right')}</button><button class="gallery-control next" data-photo="1" aria-label="الصورة التالية">${icon('left')}</button><div class="gallery-caption"><span id="gallery-label">${safe(u.labels[photoIndex]||u.name)}</span><span class="count" id="gallery-count">${photoIndex+1} / ${u.images.length}</span></div></div><div class="thumbnails">${u.images.map((src,i)=>`<button data-thumbnail="${i}" aria-label="${safe(u.labels[i]||'الصورة '+(i+1))}" aria-pressed="${photoIndex===i}"><img src="${safe(src)}" alt="" loading="lazy"></button>`).join('')}</div>`;}
function cabinNavigation(u){
 const selected=history.state?.fdPreviewRoute?.cabinFilter,garden=u.id===11;
 if(u.venue!=='resort'||garden&&selected===3)return '';
 const selectedRooms=[1,2].includes(selected)&&(garden||u.rooms===selected)?selected:0;
 const cabins=unitsFor('resort').filter(c=>!selectedRooms||c.rooms===selectedRooms),steps=[...cabins,unit(11)],index=steps.findIndex(c=>c.id===u.id);
 if(index<0)return '';
 const next=steps[index+1];
 return `<nav class="cabin-switcher" aria-label="التنقل بين الأكواخ والحديقة المشتركة">${[[steps[index-1],'الكوخ السابق','right','prev'],[next,garden||next?.id===11?'التالي':'الكوخ التالي','left','next']].map(([c,label,arrow,rel])=>c?`<a class="cabin-switch" href="${prefix(c.path)}" data-cabin-switch rel="${rel}">${icon(arrow)}<span><small>${label}</small><strong>${safe(c.name)}</strong></span></a>`:`<span class="cabin-switch unavailable" aria-disabled="true">${icon(arrow)}<span><small>${label}</small></span></span>`).join('')}<div class="cabin-browse-summary" role="status"><p>${garden?'الحديقة المشتركة':`الكوخ ${index+1} من ${cabins.length} | ${selectedRooms?rooms(selectedRooms):'الكل'}`}</p><p>عدد الأكواخ ${cabins.length} + الحديقة المشتركة</p></div></nav>`;
}

function specificationIcon(title){return /^داخل/.test(title)?'home':/المجلس/.test(title)?'sofa':/الخارجية|المسبح/.test(title)?'water':/المطبخ/.test(title)?'coffee':/معلومات/.test(title)?'clock':'spark';}
function unitSpecifications(u){
 const boxes=(items,amenities=false)=>`<div class="spec-list">${items.map(t=>`<div class="spec-item ${t.length>52||amenities&&/سماعات|غرفة سائق/.test(t)?'wide':''}">${safe(t)}</div>`).join('')}</div>`;
 return `<div class="specs">${u.sections.map(s=>{
  const resort=u.venue==='resort',stack=resort&&/^(داخل الكوخ|المنطقة الخارجية)/.test(s.title),amenities=resort&&s.title==='مميزات الإقامة',compact=resort&&(stack||amenities||s.title==='تجهيزات المطبخ');
  const groups=s.groups||[],grouped=new Set(groups.flatMap(g=>g.items));
  const items=groups.length?groups.map(g=>`<section class="spec-floor"><h3>${safe(g.title)}</h3>${boxes(g.items)}</section>`).join('')+boxes(s.items.filter(t=>!grouped.has(t))):boxes(s.items,amenities);
  const notes=u.venue==='resort'?s.notes:s.notes.flatMap(n=>n.split(/(?=يُرجى إشراف)/).map(t=>t.trim()).filter(Boolean));
  return `<details class="spec${compact?' spec-compact':''}${stack?' spec-stacked':''}"><summary>${icon(specificationIcon(s.title))}${safe(s.title)}${icon('down','chevron')}</summary><div class="spec-content">${items}${s.times.length?`<div class="spec-list">${s.times.map(t=>`<div class="spec-item"><small>${safe(t.label)}</small><br><strong>${safe(t.value)}</strong></div>`).join('')}</div>`:''}${notes.map(n=>`<p class="note">${safe(n)}</p>`).join('')}</div></details>`;
 }).join('')}${u.extras.map(e=>`<aside class="extra-note"><h3>${safe(e.title)}</h3><p>${safe(e.text)}</p></aside>`).join('')}</div>`;
}
function stayNavigation(u){
 const us=unitsFor('stay'),index=us.findIndex(c=>c.id===u.id);if(index<0)return '';
 return `<nav class="cabin-switcher stay-switcher" aria-label="التنقل بين قسمي الاستراحة">${[[us[index-1],'القسم السابق','right','prev'],[us[index+1],'القسم التالي','left','next']].map(([next,label,arrow,rel])=>next?`<a class="cabin-switch" href="${prefix(next.path)}" data-cabin-switch rel="${rel}">${icon(arrow)}<span><small>${label}</small><strong>${safe(next.name)}</strong></span></a>`:`<span class="cabin-switch unavailable" aria-disabled="true">${icon(arrow)}<span><small>${label}</small></span></span>`).join('')}<div class="cabin-browse-summary"><p>القسم ${index+1} من ${us.length}</p></div></nav>`;
}
function detail(){
 const u=currentUnit(),garden=u.id===11,v=u.venue,serviceLabel=v==='resort'?'خدمات المنتجع':v==='stay'?'خدمات الاستراحة':'خدمات الشاليه';
 return `<div class="detail-layout"><section class="detail-gallery" aria-label="صور الإقامة">${gallery(u)}</section><section class="detail-copy"><span class="eyebrow">${safe(venue().name)}</span><h1>${safe(u.name)} ${garden?'':`<span class="suitability-inline">(${safe(u.suitable)})</span>`}</h1><div class="description">${paragraphs(u.description)}</div>${garden?`<div class="fact-boxes two-facts"><div class="fact-box">${icon('pin')}<small>الموقع</small><strong>وسط الأكواخ</strong></div><div class="fact-box">${icon('users')}<small>الاستخدام</small><strong>لجميع الضيوف</strong></div></div><h2 class="content-heading" id="garden-facilities-title">مرافق الحديقة</h2><ul class="spec-list garden-facilities" aria-labelledby="garden-facilities-title">${u.gardenFeatures.map(t=>`<li class="spec-item">${safe(t)}</li>`).join('')}</ul><button class="explore-link" data-virtual="${safe(u.tour)}"><span>${icon('map')}جولة ثلاثية الأبعاد للحديقة</span>${icon('arrow')}</button>`:`<div class="fact-boxes">${[['users','سعة الضيوف',guests(u.guests)],['bed','غرف النوم',rooms(u.rooms)],['bath','الحمامات',u.bathrooms===1?'حمام واحد':u.bathrooms===2?'حمامان':u.bathrooms+' حمامات']].map(([i,t,a])=>`<div class="fact-box">${icon(i)}<small>${t}</small><strong>${a}</strong></div>`).join('')}</div>${u.tour?link(u.tour,`<span>${icon('map')}استكشف مرافق ${v==='chalet'?'الشاليه':'الكوخ'} من الداخل</span>${icon('arrow')}`,'explore-link cabin-explore-primary'):''}${unitSpecifications(u)}`}<div class="detail-actions">${garden||v==='resort'?'':link(servicesPath(),icon('services')+serviceLabel,'button outline wide')}${v==='resort'?'':link('/'+v+'/faq/','الأسئلة الشائعة '+icon('arrow'),'button outline wide')}</div>${v==='resort'?cabinNavigation(u):v==='stay'?stayNavigation(u):''}</section></div>`;
}

function serviceCard(s){return link(servicePath(s),`<div><h3>${safe(s.name)}</h3>${['cinema','coordination','competition','video'].includes(s.id)?`<p>${safe(s.intro)}</p>`:''}</div>${icon('arrow')}`,'service-card');}
function services(){if(route.venue==='stay')return `${heading('خدمات الاستراحة')}<aside class="extra-note"><h3>الفحم وأدوات الشواء</h3><p>تتوفر شواية في كل قسم ويمكن طلب الفحم وأدوات الشواء برسوم إضافية</p></aside><div class="detail-actions">${out('https://wa.me/966556156693?text='+encodeURIComponent('السلام عليكم أرغب بالاستفسار عن الفحم وأدوات الشواء في استراحة يوم العائلة'),'استفسر عبر واتساب','button primary wide')}</div>`;const ss=catalog.services.filter(s=>venue().services.includes(s.id)),groups=[...new Set(ss.map(s=>s.group))];return `${heading(route.venue==='resort'?'خدمات منتجع يوم العائلة':'خدمات الشاليه')}${groups.map(g=>`<section class="service-group"><h2>${safe(g)}</h2><div class="services-list">${ss.filter(s=>s.group===g).map(serviceCard).join('')}</div></section>`).join('')}${route.venue==='resort'?`<div class="section-heading"><h2>أثناء إقامتكم</h2></div>${link('/guest-services/',`<span>${icon('services')}خدمات إقامتك وطلبات إضافية</span>${icon('arrow')}`,'explore-link')}${link('/services-guide/',`<span>${icon('flower')}دليل تجهيز المناسبات</span>${icon('arrow')}`,'explore-link')}`:''}`;}
const displayServiceImage=src=>runtimeConfig.serviceImages?.[String(src).split('?')[0]]||src;
const warmedServiceImages=new Map();
function warmServiceImages(){if(route.venue!=='resort'||!['services','service','guest','guide'].includes(route.type)||navigator.connection?.saveData)return;const services=route.type==='service'?[route.service]:catalog.services;for(const s of services){if(!s?.image)continue;const src=displayServiceImage(s.image);if(warmedServiceImages.has(src))continue;const image=new Image();image.decoding='async';image.fetchPriority=route.type==='service'?'high':'low';image.src=src;image.decode?.().catch(()=>{});warmedServiceImages.set(src,image);}for(const image of main.querySelectorAll('.package-image img[loading="eager"]'))image.decode?.().catch(()=>{});}
function packagePhotos(p){return p.images?.length?`<div class="package-gallery">${p.images.map((src,i)=>{const size=guideCopy.serviceImageSizes?.[src.split('?')[0]],resort=route.venue==='resort',eager=resort&&i===0;return `<button type="button" class="package-image" data-package-photo="${safe(src)}" aria-label="تكبير صورة ${safe(p.name)} ${i+1}"><img src="${safe(resort?displayServiceImage(src):src)}" alt="${safe(p.name)} ${i+1}" ${size?`width="${size[0]}" height="${size[1]}"`:''} loading="${eager?'eager':'lazy'}" decoding="async" ${eager?'fetchpriority="high"':''}></button>`;}).join('')}</div>`:'';}
function orderButton(action,label='أضف للطلب',disabled=false){return `<button type="button" class="button primary wide" data-add="${safe(action)}" ${disabled?'disabled':''}>${label}</button>`;}
function restaurantGuide(s){return `<section class="restaurant-guide">${heading(s.name,s.intro)}<div class="restaurant-hours">${icon('clock')}<p>${safe(catalog.source.guestCatalog.restaurantHours)}</p></div><section class="restaurant-overview" aria-labelledby="restaurant-categories-title"><h2 id="restaurant-categories-title">الطعام والمشروبات</h2><ul class="restaurant-categories">${Object.keys(s.menu).map(category=>`<li>${safe(category)}</li>`).join('')}</ul></section><a class="button primary wide restaurant-order-link" data-service-portal href="https://familydaystay.com/guest-services/#restaurant">عرض المنيو والطلب ${icon('arrow')}</a></section>`;}
function diningGuide(s){return `<section class="dining-guide">${heading(s.name,s.intro)}<div class="dining-guide-options"><div><h2>تجهيز أساسي</h2><p>طاولات وكراسي فقط</p></div><div><h2>تجهيز مع تنسيق</h2><p>طاولات وكراسي مع تجهيز الطاولة</p></div></div><div class="dining-guide-prices"><div class="dining-guide-table"><table><caption class="sr-only">أسعار طاولات الطعام بالريال</caption><thead><tr><th scope="col">عدد الأشخاص</th><th scope="col">تجهيز أساسي</th><th scope="col">تجهيز مع تنسيق</th></tr></thead><tbody>${Object.entries(s.prices).map(([size,price])=>`<tr><th scope="row"><bdi>${safe(size)}</bdi></th><td><bdi>${safe(price.plain)}</bdi></td><td><bdi>${safe(price.tansiq)}</bdi></td></tr>`).join('')}</tbody></table></div><p class="dining-guide-currency">الأسعار بالريال</p></div><details class="dining-guide-details"><summary>صورة ومحتويات التجهيز مع تنسيق ${icon('down')}</summary><figure>${packagePhotos({images:[s.image],name:s.name})}<figcaption>الصورة توضح التجهيز مع تنسيق</figcaption></figure>${ul(s.items)}</details><a class="button primary wide dining-guide-link" data-service-portal href="https://familydaystay.com/arrangements/#dining">عرض الخدمة والتواصل ${icon('arrow')}</a></section>`;}
// The resort guide explains services; the two existing portals own requests and contact.
function resortServiceLink(id){const arrangements=['dining','coordination','seating'].includes(id);return `<a class="button primary wide service-guide-link" data-service-portal href="https://familydaystay.com/${arrangements?'arrangements':'guest-services'}/#${safe(id)}">${arrangements?'عرض الخدمة والتواصل':'عرض الخدمة والطلب'} ${icon('arrow')}</a>`;}
function guideNotes(notes){return notes?.length?`<aside class="service-guide-notes">${notes.map(n=>`<p>${safe(n)}</p>`).join('')}</aside>`:'';}
function guidePhotos(s,items,title='الصورة ومحتويات الخدمة'){return `<details class="package service-guide-details"><summary><span>${safe(title)}</span>${icon('down')}</summary><div class="package-body">${packagePhotos({name:s.name,images:s.image?[s.image]:[]})}${ul(items)}</div></details>`;}
function serviceGuidePackage(p,i,{seating=false,share=false}={}){const key=p.id?.replace('hd-coordination-package-',''),selected=key&&route.params.get('package')===key;return `<details class="package" data-remember="guide-package-${i}" ${selected?'open':''}><summary><span>${safe(p.name)}${seating?`<small class="service-guide-capacity">${safe(p.persons)}</small>`:''}</span><span class="package-price">${safe(p.price)}</span>${icon('down')}</summary><div class="package-body">${packagePhotos(seating?{name:p.name,images:[p.img]}:p)}${p.description?`<p class="note">${safe(p.description)}</p>`:''}${seating?`<div class="note">${paragraphs(p.desc)}</div>`:ul(p.items)}${p.note?`<p class="note">${safe(p.note)}</p>`:''}${share?`<button class="text-link share-text" data-share="${safe(servicePath(route.service)+'?package='+key)}">${icon('share')}مشاركة الباقة</button>`:''}</div></details>`;}
function resortServiceGuide(s){const source=catalog.source.guestCatalog[s.id];let body='';
 if(s.id==='games')body=`<div class="service-guide-prices">${s.packages.map(p=>`<article><h2>${safe(p.name)}</h2><strong>${safe(p.price)}</strong><p>${safe(p.note)}</p></article>`).join('')}</div>${guidePhotos(s,s.items,'الصورة والألعاب المشمولة في الباقتين')}${guideNotes(source.notes)}`;
 if(s.id==='water')body=`<div class="price-highlight">${safe(s.offer)}</div><p class="service-guide-explanation">يمكن توزيع الألعاب بين الكبار والأطفال.</p>${guideNotes(source.notes)}`;
 if(s.id==='cinema')body=`<div class="fact-boxes two-facts">${s.stats.map(t=>`<div class="fact-box"><small>${safe(t.label)}</small><strong>${safe(t.value)}</strong></div>`).join('')}</div>${guidePhotos(s,s.items,'الصورة ومحتويات الجلسة')}${guideNotes(source.notes)}`;
 if(['hospitality','coordination'].includes(s.id))body=`<div class="service-guide-packages">${s.packages.map((p,i)=>serviceGuidePackage(p,i,{share:s.id==='coordination'})).join('')}</div>`;
 if(s.id==='seating')body=`<div class="service-guide-packages">${s.sessions.map((p,i)=>serviceGuidePackage(p,i,{seating:true})).join('')}</div><div class="service-guide-extra"><h2>إضافة اختيارية</h2><p><span>كيك وعصير</span><strong>170 ريال</strong></p></div>${guideNotes(catalog.source.notes.seating)}`;
 return `<section class="service-guide">${heading(s.name,s.id==='cinema'?source.intro:s.intro)}${body}${resortServiceLink(s.id)}</section>`;
}
function resortGuestGuide(){return `<section class="service-guide">${heading('خدمات إقامتك','تعرّف على الخدمات والطلبات الإضافية المتاحة أثناء إقامتكم')}<div class="services-list">${['hospitality','water','games','cinema','menu'].map(id=>serviceCard(serviceBy(id))).join('')}</div><section class="service-guide-extras" id="extras"><h2>طلبات إضافية</h2>${catalog.source.extras.map(p=>`<article class="service-guide-extra"><div><h3>${safe(p.name)}</h3>${p.description?`<p class="note">${safe(p.description)}</p>`:''}</div><strong>${money(p.price)}</strong></article>`).join('')}</section>${resortServiceLink('extras')}</section>`;}
function serviceDetail(){const s=route.service;if(!s||!venue().services.includes(s.id))return unavailable();if(route.venue==='resort'&&s.id==='menu')return restaurantGuide(s);if(route.venue==='resort'&&s.id==='dining')return diningGuide(s);if(route.venue==='resort'&&['games','water','cinema','hospitality','coordination','seating'].includes(s.id))return resortServiceGuide(s);if(route.venue==='resort'&&['competition','video','loyalty'].includes(s.id))return promotionGuide(s);const d=draft(s.id);let body='';
 if(s.id==='menu')body=menuView();
 if(['hospitality','coordination'].includes(s.id))body=s.packages.map((p,i)=>`<details class="package" data-remember="package-${i}" ${route.params.get('package')===p.id?.replace('hd-coordination-package-','')?'open':''}><summary><span>${safe(p.name)}</span><span class="package-price">${safe(p.price)}</span>${icon('down')}</summary><div class="package-body">${packagePhotos(p)}${p.description?`<p class="note">${safe(p.description)}</p>`:''}${ul(p.items)}${p.note?`<p class="note">${safe(p.note)}</p>`:''}<div class="quantity-row"><span>عدد الباقات</span>${qtyControl('package:'+i,d['package'+i]||1,1)}</div>${orderButton('package:'+i)}<button class="text-link share-text" data-share="${safe(servicePath(s)+(s.id==='coordination'?'?package='+p.id.replace('hd-coordination-package-',''):''))}">${icon('share')}مشاركة الباقة</button></div></details>`).join('');
 if(s.id==='games'){const option=d.option||'box';body=`<fieldset class="choice-field"><legend>اختر باقة الألعاب</legend>${s.packages.filter((_,i)=>route.venue!=='chalet'||i===0).map((p,i)=>`<label class="choice ${option===(i?'table':'box')?'selected':''}"><input type="radio" name="games" data-choice="option" value="${i?'table':'box'}" ${option===(i?'table':'box')?'checked':''}><span><strong>${safe(p.name)}</strong><small>${safe(p.note)}</small></span><b>${safe(p.price)}</b></label>`).join('')}</fieldset>${ul(s.items)}<div class="quantity-row"><span>الكمية</span>${qtyControl('qty',d.qty||1,1)}</div>${orderButton('games')}${usage(catalog.source.notes.games)}`;}
 if(s.id==='water'){const pack=d.packages||1,a=d.adults||0,c=d.children||0,required=3*pack;body=`<div class="price-highlight">${required} ألعاب بـ${50*pack} ريال</div><div class="quantity-row"><span>عدد الباقات</span>${qtyControl('packages',pack,1,20)}</div><p class="note">وزّع الألعاب بين الكبار والأطفال</p><div class="quantity-row"><span>للكبار</span>${qtyControl('adults',a,0,required-c)}</div><div class="quantity-row"><span>للأطفال</span>${qtyControl('children',c,0,required-a)}</div><p class="selection-status" role="status">${a+c===required?'اكتمل اختيار الألعاب':'اخترت '+(a+c)+' من '+required}</p>${orderButton('water','أضف للطلب',a+c!==required)}${usage(s.notes)}`;}
 if(s.id==='cinema')body=`<div class="fact-boxes two-facts">${s.stats.map(t=>`<div class="fact-box"><small>${safe(t.label)}</small><strong>${safe(t.value)}</strong></div>`).join('')}</div><h2 class="content-heading">محتويات الجلسة</h2>${ul(s.items)}<label class="form-field">وقت بداية الجلسة<select data-choice="time"><option value="">اختر الوقت</option>${catalog.source.times.map(t=>`<option value="${t.value}" ${d.time===t.value?'selected':''}>${safe(t.label)}</option>`).join('')}</select></label>${d.time?`<p class="note">${cinemaRange(d.time)}</p>`:''}${orderButton('cinema','أضف للطلب',!d.time)}${usage(catalog.source.notes.cinema)}`;
 if(s.id==='dining'){const size=d.size||'6',option=d.option||'plain',p=s.prices[size];body=`<h2 class="content-heading">عدد الأشخاص</h2><div class="filters">${Object.keys(s.prices).map(n=>`<button class="filter" data-dining-size="${n}" aria-pressed="${size===n}">${n} أشخاص</button>`).join('')}</div><fieldset class="choice-field"><legend>اختر التجهيز</legend>${[['plain','تجهيز أساسي'],['tansiq','تجهيز مع تنسيق']].map(([v,t])=>`<label class="choice ${option===v?'selected':''}"><input type="radio" name="dining" data-choice="option" value="${v}" ${option===v?'checked':''}><strong>${t}</strong><b>${money(p[v])}</b></label>`).join('')}</fieldset>${ul(s.items.filter(t=>option==='tansiq'||!/زهور|شموع/.test(t)))}<div class="price-highlight">${money(p[option])}</div>${orderButton('dining')}`;}
 if(s.id==='seating')body=s.sessions.map((p,i)=>`<details class="package" data-remember="session-${i}"><summary><span>${safe(p.name)}<small class="muted"> · ${safe(p.persons)}</small></span><span class="package-price">${safe(p.price)}</span>${icon('down')}</summary><div class="package-body">${packagePhotos({...p,images:[p.img]})}<div class="note">${paragraphs(p.desc)}</div><div class="quantity-row"><span>عدد الجلسات</span>${qtyControl('session:'+i,d['session'+i]||1,1)}</div><h3 class="content-heading">إضافة اختيارية</h3><label class="addon"><input type="checkbox" data-cake="${i}" ${d['cake'+i]?'checked':''}><span>كيك وعصير</span><strong>170 ريال</strong></label>${d['cake'+i]?`<div class="quantity-row"><span>عدد إضافات الكيك والعصير</span>${qtyControl('cakes:'+i,d['cakes'+i]||1,1,d['session'+i]||1)}</div>`:''}<div class="price-highlight">${money(number(p.price)*(d['session'+i]||1)+(d['cake'+i]?170*(d['cakes'+i]||1):0))}</div>${orderButton('seating:'+i)}</div></details>`).join('')+usage(catalog.source.notes.seating);
 return `<div class="service-detail">${heading(s.name)}${s.id!=='menu'?(s.image?`<div class="service-detail-hero"><img src="${safe(s.image)}" alt="${safe(s.name)}" fetchpriority="high"></div>`:`<div class="service-icon-hero">${icon(s.icon)}</div>`):''}<p class="intro">${safe(s.id==='menu'?catalog.source.hours:s.id==='loyalty'?'استمتع بمزايا حصرية مع بطاقة ولاء يوم العائلة':s.intro)}</p>${body}</div>`;
}
function usage(notes){return notes?.length?`<details class="spec" data-remember="usage"><summary>تعليمات الاستخدام${icon('down','chevron')}</summary><div class="spec-content">${notes.map(n=>`<p class="note">${safe(n)}</p>`).join('')}</div></details>`:'';}
function cinemaRange(value){const h=Number(value),label=x=>{const hr=x%24;return `${hr%12||12}:00 ${hr>=12?'مساءً':'صباحًا'}`;};return 'من '+label(h)+' إلى '+label(h+3)+(h+3>=24&&h<24?' في اليوم التالي':'');}
function menuView(){const d=draft('menu');return `<div class="menu-categories">${Object.entries(serviceBy('menu').menu).map(([category,items],ci)=>`<details class="package" data-remember="menu-${ci}"><summary><span>${safe(category)}</span>${icon('down')}</summary><div class="package-body">${items.map((item,pi)=>(item.bbq?['لحم','دجاج']:['']).map(variant=>{const key=ci+':'+pi+':'+variant,qty=d[key]||0;return `<article class="menu-order-row"><div><h3>${safe(item.name+(variant?' — '+variant:''))}</h3>${item.desc?`<p class="note">${safe(item.desc)}</p>`:''}<strong class="menu-price">${money(item.price)}</strong></div>${qtyControl('menu:'+key,qty,0)}${item.cheesePrice?`<label class="cheese-option"><input type="checkbox" data-cheese="${safe(key)}" ${d['cheese:'+key]?'checked':''}>إضافة جبن ${item.cheesePrice} ريال للقطعة</label>`:''}</article>`;}).join('')).join('')}</div></details>`).join('')}</div><div class="detail-actions">${orderButton('menu','أضف اختيارات المطعم للطلب',!Object.keys(d).some(k=>!k.startsWith('cheese:')&&d[k]>0))}</div>`;}
function promotionList(items){return `<ul class="promotion-list">${items.map(t=>`<li>${safe(t)}</li>`).join('')}</ul>`;}
function promotionDisclosure(title,body){return `<details class="promotion-details"><summary><span>${safe(title)}</span>${icon('down')}</summary><div class="promotion-details-body">${body}</div></details>`;}
function promotionAction(a,primary=false){return `<a class="button ${primary?'primary':'outline'} wide" href="${safe(a.href)}" ${a.href.startsWith('mailto:')?'':'target="_blank" rel="noopener noreferrer"'}>${safe(a.text)} ${icon('arrow')}</a>`;}
function promotionSteps(steps){return `<section class="promotion-how" aria-labelledby="promotion-how-title"><h2 id="promotion-how-title">طريقة المشاركة</h2><ol class="promotion-steps">${steps.map(([title,copy],i)=>`<li><span class="promotion-step-number" aria-hidden="true">${i+1}</span><div><h3>${safe(title)}</h3><p>${safe(copy)}</p></div></li>`).join('')}</ol></section>`;}
function promotionSocial(links){return `<div class="promotion-social">${links.map(a=>{const snap=a.href.includes('snapchat'),name=snap?'سناب شات':a.href.includes('instagram')?'إنستقرام':'تيك توك',handle=snap?'familyday5':'familydayresort';return `<article class="promotion-social-card"><div><h3>${name}</h3><bdi>@${handle}</bdi></div><div class="promotion-social-actions"><a class="button outline" href="${safe(a.href)}" target="_blank" rel="noopener noreferrer" aria-label="زيارة حساب ${name}">${safe(a.text)}</a><button type="button" class="button outline" data-copy="${handle}" aria-label="نسخ اسم مستخدم ${name}">نسخ اسم المستخدم</button></div></article>`;}).join('')}</div>`;}
function promotionGuide(s){const c=catalog.source.campaigns.find(c=>c.id===({competition:'contest-detail',video:'sharik-detail',loyalty:'walaa-detail'}[s.id]));if(!c)return unavailable();const sec=title=>c.sections.find(section=>section.title===title);let body='';
 if(s.id==='competition'){const choose=sec('اختر فيديو للمشاركة'),terms=sec('شروط المشاركة'),submit=sec('أرسل مشاركتك');body=`<div class="promotion-reward"><p class="promotion-kicker">${safe(c.paragraphs[0])}</p><h2>يوم مجاني في منتجع يوم العائلة</h2><p>${safe(c.paragraphs[1])}</p></div>${promotionSteps([[choose.title,choose.paragraphs[0]],[submit.title,submit.paragraphs[0]]])}${promotionDisclosure(terms.title,`${promotionList(terms.items)}<h3>معيار اختيار الفائز</h3>${terms.paragraphs.map(t=>`<p>${safe(t)}</p>`).join('')}`)}${promotionDisclosure('حساباتنا للمنشن',promotionSocial(terms.links))}<div class="promotion-actions">${choose.links.map(a=>promotionAction(a)).join('')}${submit.links.map(a=>promotionAction(a,true)).join('')}</div>`;}
 if(s.id==='video'){const how=sec('طريقة المشاركة'),terms=sec('شروط المشاركة'),criteria=sec('معايير الاختيار'),submit=sec('إرسال المشاركة'),email=new URL(c.links[0].href).pathname;body=`<div class="promotion-reward"><p class="promotion-kicker">${safe(c.paragraphs[0])}</p><h2>${safe(c.headings[0])}</h2></div>${promotionSteps([[c.headings[2],how.paragraphs[0]],[c.headings[3],how.paragraphs[1]]])}${promotionDisclosure(terms.title,promotionList(terms.items))}${promotionDisclosure(criteria.title,`${promotionList(criteria.items)}${criteria.paragraphs.map(t=>`<p>${safe(t)}</p>`).join('')}`)}<section class="promotion-contact" aria-labelledby="promotion-contact-title"><h2 id="promotion-contact-title">${safe(submit.title)}</h2><div class="promotion-email"><bdi>${safe(email)}</bdi><button type="button" class="text-link" data-copy="${safe(email)}">نسخ الإيميل</button></div>${submit.links.map(a=>promotionAction(a,true)).join('')}</section>`;}
 if(s.id==='loyalty'){const benefits=sec('مزايا البطاقة');body=`<div class="promotion-reward promotion-loyalty"><h2>${safe(c.headings[0])}</h2><p>${safe(c.paragraphs[0])}</p><ol class="promotion-stamps" aria-label="ثلاثة حجوزات ثم الحجز الرابع مجانًا">${['الأول','الثاني','الثالث','مجانًا'].map((label,i)=>`<li${i===3?' class="is-reward"':''}><span aria-hidden="true">${i+1}</span><small>${i===3?'الرابع':'الحجز'}<br>${label}</small></li>`).join('')}</ol></div><section class="promotion-benefits" aria-labelledby="promotion-benefits-title"><h2 id="promotion-benefits-title">${safe(benefits.title)}</h2>${ul(benefits.items)}</section><div class="promotion-actions">${c.links.map(a=>promotionAction(a,true)).join('')}</div>`;}
 return `<section class="promotion-guide promotion-${safe(s.id)}">${heading(s.name)}${body}</section>`;
}
function entryKey(e){return [e.venue,e.service,e.index??'',e.option??'',e.size??'',e.variant??'',e.category??''].join('|');}
function priced(e){if(!e||e.venue!==route.venue||!Number.isInteger(e.qty)||e.qty<1||e.qty>99)return null;const s=serviceBy(e.service);if(e.venue==='chalet'&&!['games','water'].includes(e.service))return null;if(e.venue==='stay')return null;let name='',base=0,group='services',details=[],qty=e.qty;
 if(e.service==='menu'){const product=Object.entries(s.menu)[e.category]?.[1]?.[e.index];if(!product||!['','لحم','دجاج'].includes(e.variant||'')||(product.bbq&&!['لحم','دجاج'].includes(e.variant)))return null;name=product.name+(e.variant?' — '+e.variant:'');base=product.price+(product.cheesePrice&&e.cheese?product.cheesePrice:0);if(e.cheese)details.push('إضافة جبن لكل قطعة');group='restaurant';}
 else if(e.service==='water'){if(!Number.isInteger(e.adults)||!Number.isInteger(e.children)||e.adults<0||e.children<0||e.adults+e.children!==3*qty||qty>20)return null;name='باقة ألعاب مائية';base=50;details=['للكبار: '+e.adults,'للأطفال: '+e.children];}
 else if(e.service==='games'){if(e.venue==='chalet'&&e.option!=='box')return null;const p=s.packages[e.option==='box'?0:e.option==='table'?1:-1];if(!p)return null;name=p.name;base=number(p.price);}
 else if(e.service==='cinema'){if(!catalog.source.times.some(t=>t.value===e.time))return null;name='جلسة السينما';base=150;details=[cinemaRange(e.time)];}
 else if(e.service==='dining'){if(!s.prices[e.size]||!['plain','tansiq'].includes(e.option))return null;name='طاولات الطعام';base=s.prices[e.size][e.option];details=['عدد الأشخاص: '+e.size,e.option==='plain'?'تجهيز أساسي':'تجهيز مع تنسيق'];}
 else if(['hospitality','coordination'].includes(e.service)){const p=s.packages[e.index];if(!p)return null;name=p.name;base=number(p.price);if(e.service==='coordination')group='coordinator';}
 else if(e.service==='seating'){const p=s.sessions[e.index];if(!p||!Number.isInteger(e.cakes)||e.cakes<0||e.cakes>qty)return null;name=p.name;base=number(p.price);if(e.cakes)details=['كيك وعصير × '+e.cakes+' = '+170*e.cakes+' ريال'];return {...e,name,group,base,details,total:base*qty+170*e.cakes,key:entryKey(e)};}
 else if(e.service==='extras'){const p=catalog.source.extras.find(p=>p.id===e.option);if(!p)return null;name=p.name;base=p.price;}else return null;
 return {...e,name,base,group,details,total:base*qty,key:entryKey(e)};
}
function cartItems(group){return state.cart.map(priced).filter(e=>e&&(!group||e.group===group));}
function cartPath(){return '/'+route.venue+'/order/';}
function cartRows(items,removable=true){return `<div class="cart-items">${items.map(e=>`<article class="cart-row"><div><h3>${safe(e.name)}</h3><p>${e.qty} × ${e.base} ريال</p>${e.details.map(t=>`<small>${safe(t)}</small>`).join('')}</div><strong>${money(e.total)}</strong>${removable?`<button type="button" class="text-link" data-remove="${safe(e.key)}" aria-label="حذف ${safe(e.name)}">حذف</button>`:''}</article>`).join('')}</div>`;}
function cartView(){const items=cartItems();return `<div class="service-detail">${heading('ملخص طلبكم')}${!items.length?`<div class="empty">ما أضفت أي طلب حتى الآن</div>${link(servicesPath(),'تصفّح الخدمات','button primary wide')}`:[...new Set(items.map(e=>e.group))].map(g=>{const rows=items.filter(e=>e.group===g);return `<section class="content-section"><h2>${({restaurant:'طلبات المطعم',coordinator:'تجهيز مناسبتكم',services:'خدمات إقامتكم'}[g])}</h2>${cartRows(rows)}<div class="order-total"><span>الإجمالي</span><strong>${money(rows.reduce((n,e)=>n+e.total,0))}</strong></div>${link('/'+route.venue+'/checkout/?group='+g,'متابعة الطلب '+icon('arrow'),'button primary wide')}</section>`;}).join('')}${items.length?link(servicesPath(),'إضافة خدمات أخرى','text-link'):''}</div>`;}
function checkout(){const group=route.params.get('group')||'services',items=cartItems(group),customer=state.customer;if(!items.length)return cartView();const coordinator=group==='coordinator';return `<div class="service-detail">${heading('تفاصيل طلبكم')}${cartRows(items,false)}<div class="order-total"><span>إجمالي الطلب</span><strong>${money(items.reduce((n,e)=>n+e.total,0))}</strong></div><form id="checkout-form" class="checkout-form"><label class="form-field" for="customer-name">الاسم<input id="customer-name" name="name" autocomplete="name" required maxlength="80" value="${safe(customer.name)}"></label>${route.venue==='resort'?`<label class="form-field" for="customer-cabin">اختر الكوخ<select id="customer-cabin" name="cabin" required><option value="">اختر الكوخ</option>${Object.keys(catalog.source.cabins).map(n=>`<option value="${safe(n)}" ${customer.cabin===n?'selected':''}>${safe(n)} — ${catalog.source.cabins[n]}</option>`).join('')}</select></label>`:`<div class="spec-item">المكان: شاليه يوم العائلة</div>`}${coordinator?`<label class="form-field" for="occasion-date">تاريخ المناسبة<input id="occasion-date" type="date" name="date" required></label>`:''}<label class="form-field" for="customer-notes">ملاحظاتك <small>اختياري</small><textarea id="customer-notes" name="notes" rows="3" maxlength="1000">${safe(customer.notes)}</textarea></label><p class="note">تفتح رسالة طلبك في واتساب لتراجعها وترسلها بنفسك</p><button class="button primary wide" type="submit">إرسال الطلب عبر واتساب ${icon('arrow')}</button></form></div>`;}
function addToCart(action){const s=route.service||{id:'extras'},d=draft(s.id);let e={venue:route.venue,service:s.id,qty:d.qty||1};
 if(action==='games')e.option=d.option||'box';
 else if(action==='water'){e.qty=d.packages||1;e.adults=d.adults||0;e.children=d.children||0;}
 else if(action==='cinema'){e.qty=1;e.time=d.time;}
 else if(action==='dining'){e.qty=1;e.size=d.size||'6';e.option=d.option||'plain';}
 else if(action.startsWith('package:')){e.index=Number(action.split(':')[1]);e.qty=d['package'+e.index]||1;}
 else if(action.startsWith('seating:')){e.index=Number(action.split(':')[1]);e.qty=d['session'+e.index]||1;e.cakes=d['cake'+e.index]?(d['cakes'+e.index]||1):0;}
 else if(action.startsWith('extras:')){e={venue:route.venue,service:'extras',option:action.split(':')[1],qty:Number(draft('extras')[action.split(':')[1]]||1)};}
 else if(action==='menu'){let added=false;Object.entries(s.menu).forEach(([_,products],category)=>products.forEach((p,index)=>(p.bbq?['لحم','دجاج']:['']).forEach(variant=>{const key=category+':'+index+':'+variant;if(d[key]>0){putCart({venue:route.venue,service:'menu',category,index,variant,qty:d[key],cheese:!!d['cheese:'+key]});added=true;}})));if(!added)return;save();refreshCartShortcut();toast('تمت إضافة اختيارات المطعم');return;}
 const valid=priced(e);if(!valid){toast('أكمل اختيار الخدمة');return;}putCart(e);save();refreshCartShortcut();toast('تمت الإضافة إلى الطلب');}
function putCart(e){const key=entryKey(e);e.storageKey=key;const i=state.cart.findIndex(x=>x.storageKey===key);if(i>=0)state.cart[i]=e;else state.cart.push(e);}
function refreshCartShortcut(){let shortcut=$('#cart-shortcut');if(!shortcut){shortcut=document.createElement('a');shortcut.id='cart-shortcut';shortcut.className='cart-shortcut';document.body.appendChild(shortcut);}const items=cartItems();shortcut.hidden=route.venue==='resort'||['destinations','map','tour'].includes(route.type)||!items.length||['cart','checkout'].includes(route.type);shortcut.href=prefix(cartPath());shortcut.innerHTML=`<span>${icon('services')}طلبكم · ${items.length}</span><strong>${money(items.reduce((n,e)=>n+e.total,0))}</strong>`;}
function submitOrder(form){if(!form.reportValidity())return;const fd=new FormData(form),group=route.params.get('group')||'services',items=cartItems(group);const name=String(fd.get('name')||'').trim(),cabin=String(fd.get('cabin')||''),notes=String(fd.get('notes')||'').trim();if(!name||!items.length||route.venue==='resort'&&!Object.hasOwn(catalog.source.cabins,cabin)){toast('أكمل الاسم واختيار الكوخ');return;}state.customer={name,cabin,notes};save();let lines=['السلام عليكم أرغب بطلب '+({restaurant:'من المطعم',coordinator:'تجهيز مناسبة',services:'الخدمات التالية'}[group]),'','الاسم: '+name];if(route.venue==='chalet')lines.push('المكان: شاليه يوم العائلة');else lines.push('الكوخ: '+cabin,'رقم الكوخ: '+catalog.source.cabins[cabin]);if(fd.get('date'))lines.push('تاريخ المناسبة: '+fd.get('date'));lines.push('','الطلبات:');items.forEach(e=>{lines.push('',e.name+' × '+e.qty+' = '+e.total+' ريال',...e.details);});lines.push('','إجمالي الطلب: '+items.reduce((n,e)=>n+e.total,0)+' ريال');if(notes)lines.push('','ملاحظات: '+notes);const phone=group==='restaurant'?'966537006531':group==='coordinator'?'966537009217':'966556156693';window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener,noreferrer');}
function contact(){return venueContact();}

function faqSearchText(text){return digit(roomWording(text)).normalize('NFKD').replace(/\p{M}/gu,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').toLowerCase().trim();}
function faqGuide(){const groups=guideCopy.faqs[route.venue].groups,source=new Map(venue().faqs.map(q=>[q.question,q]));return `<section class="faq-guide" data-faq-group="${safe(groups[0].id)}">${heading('الأسئلة الشائعة')}<div class="faq-tools"><nav class="faq-categories" aria-label="أقسام الأسئلة الشائعة">${groups.map((g,i)=>`<button type="button" data-faq-group="${safe(g.id)}" aria-controls="faq-group-${safe(g.id)}" aria-pressed="${i===0}">${safe(g.label)}</button>`).join('')}</nav><label class="search-field">${icon('search')}<input type="search" id="faq-search" placeholder="ابحث في كل الأسئلة" aria-label="ابحث في كل الأسئلة" autocomplete="off"></label><div class="faq-search-feedback" hidden><p id="faq-results" role="status" aria-live="polite"></p><button type="button" id="faq-clear" class="text-link">مسح البحث</button></div></div><div class="faq-groups">${groups.map((g,i)=>`<section class="faq-group" id="faq-group-${safe(g.id)}" aria-labelledby="faq-heading-${safe(g.id)}" ${i?'hidden':''}><h2 id="faq-heading-${safe(g.id)}">${safe(g.title)}</h2><div class="faq-list">${g.items.map(item=>{const originals=item.sources.map(q=>source.get(q)),answers=(item.answers||originals.map(q=>q.answer)).map(a=>a.replace('على الرقم ،','على الرقم '+venue().phone.replace(/^\+966/,'0')+'،')),question=item.question||originals[0].question,index=[question,...item.sources,...originals.map(q=>q.answer),...answers].join(' ');return `<details class="faq" id="faq-${safe(item.id)}" data-question="${safe(index)}"><summary>${safe(question)}${icon('down')}</summary><div class="faq-answer">${answers.map(a=>`<p>${safe(a)}</p>`).join('')}${item.links?`<div class="faq-answer-links">${item.links.map(a=>link(a.path,safe(a.text),'text-link')).join('')}</div>`:''}</div></details>`;}).join('')}</div></section>`).join('')}</div><p id="faq-empty" class="empty" hidden>ما لقينا سؤالًا مطابقًا. جرّب كلمة ثانية.</p></section>`;}
function bindFaqGuide(){const root=$('.faq-guide'),input=$('#faq-search',root),buttons=[...root.querySelectorAll('button[data-faq-group]')],groups=[...root.querySelectorAll('.faq-group')],questions=[...root.querySelectorAll('.faq')],feedback=$('.faq-search-feedback',root),snap=navViews[activeEntryId]?.faq;let active=buttons.some(b=>b.dataset.faqGroup===snap?.group)?snap.group:buttons[0].dataset.faqGroup;
 const update=()=>{const query=faqSearchText(input.value),words=query.split(/\s+/).filter(Boolean);let count=0;root.dataset.faqGroup=active;root.classList.toggle('is-searching',!!query);questions.forEach(q=>{q.hidden=!!query&&!words.every(word=>faqSearchText(q.dataset.question).includes(word));if(!q.hidden)count++;});groups.forEach(group=>{group.hidden=query?!group.querySelector('.faq:not([hidden])'):group.id!=='faq-group-'+active;});buttons.forEach(b=>b.setAttribute('aria-pressed',String(!query&&b.dataset.faqGroup===active)));feedback.hidden=!query;$('#faq-results',root).textContent=query?`${count} نتيجة في كل الأقسام`:'';$('#faq-empty',root).hidden=!query||count>0;};
 input.value=snap?.query||'';update();if(snap?.open){const q=document.getElementById(snap.open);if(q?.matches('.faq')&&!q.hidden&&!q.closest('.faq-group').hidden)q.open=true;}
 input.addEventListener('input',()=>{questions.forEach(q=>q.open=false);update();});buttons.forEach(b=>b.addEventListener('click',()=>{active=b.dataset.faqGroup;input.value='';questions.forEach(q=>q.open=false);update();}));$('#faq-clear',root).addEventListener('click',()=>{input.value='';update();input.focus({preventScroll:true});});root.addEventListener('toggle',e=>{if(e.target.matches('.faq[open]'))questions.forEach(q=>{if(q!==e.target)q.open=false;});},true);
}

function faq(){
 if(guideCopy.faqs?.[route.venue])return faqGuide();
 const answer=q=>route.venue!=='resort'?q.answer.replace('على الرقم ،','على الرقم '+venue().phone.replace(/^\+966/,'0')):q.answer;
 return `<div class="service-detail">${heading('الأسئلة الشائعة',venue().name)}<label class="search-field">${icon('info')}<input type="search" id="faq-search" placeholder="ابحث في الأسئلة" aria-label="ابحث في الأسئلة"></label><div class="faq-list">${venue().faqs.map(q=>`<details class="faq" data-question="${safe(q.question+' '+answer(q))}"><summary>${safe(q.question)}${icon('down')}</summary><p>${safe(answer(q))}</p>${/أستكشف/.test(q.question)?link('/chalet-map/','استكشف مرافق الشاليه من الداخل','text-link'):/كيف أختار|أين أجد صور/.test(q.question)?link(listPath(),'التفاصيل والصور','text-link'):''}</details>`).join('')}</div><p id="faq-empty" class="empty" hidden>ما لقينا سؤالًا مطابقًا</p></div>`;
}

function comparisonSpecials(u){
 const raw=u.raw,features=[...(raw.features?.indoor||[]),...(raw.features?.outdoor||[]),...(raw.pool?.facilities||[])].filter(t=>/بانيو|جاكوزي|سرير تشميس داخل/.test(t));
 return [...new Set(features.concat(u.extras.filter(e=>e.title==='حجز الكوخين معًا').map(e=>e.text)))];
}
function resortComparison(){
 const cabins=unitsFor('resort'),selected=cabins.filter(u=>compare.has(u.id));
 const picker=`<p class="note">اختر من 2 إلى 3 أكواخ للمقارنة</p><div class="compare-picker">${cabins.map(u=>`<label class="compare-chip"><input type="checkbox" data-compare="${u.id}" ${compare.has(u.id)?'checked':''}><span>${safe(u.name)}</span></label>`).join('')}</div>`;
 const intro=heading('مقارنة الأكواخ');
 if(selected.length<2)return `${intro}${picker}<div class="comparison-empty" role="status">${icon('bed')}<p>${selected.length?'اختر كوخًا آخر لعرض المقارنة':'اختر الأكواخ التي تريد مقارنتها'}</p></div>`;
 const rows=[
  ['سعة الضيوف',u=>guests(u.guests)],
  ['لمن يناسب',u=>u.suitable],
  ['غرف النوم',u=>rooms(u.rooms)],
  ['الأسرّة',u=>(u.raw.features?.indoor||[]).filter(t=>/سرير|أسرّة|أسرة/.test(t)&&!/تشميس/.test(t))],
  ['الصالة الداخلية',u=>u.raw.livingRoom==='integrated'?'مدمجة مع غرفة النوم':u.raw.hall?'متوفرة':'غير متوفرة'],
  ['طاولة الطعام',u=>(u.raw.features?.indoor||[]).includes('طاولة طعام')?'متوفرة':'غير متوفرة'],
  ['الحمامات',u=>u.bathrooms===1?'حمام واحد':u.bathrooms===2?'حمامان':u.bathrooms+' حمامات'],
  ['المسبح',u=>u.sections.find(s=>s.title==='المنطقة الخارجية والمسبح')?.items.find(t=>/مسبح خاص/.test(t))||'—'],
  ['مميزات خاصة',comparisonSpecials]
 ];
 const formatted=text=>safe(text).replace(/(\d+\s*×\s*\d+)/g,'<bdi dir="ltr">$1</bdi>');
 const value=text=>Array.isArray(text)?text.length?text.map(t=>`<span class="comparison-fact">${formatted(t)}</span>`).join(''):'—':formatted(text);
 return `${intro}${picker}<div class="comparison-scroll ${selected.length===3?'comparison-three':''}" role="region" aria-label="جدول مقارنة الأكواخ" tabindex="0"><table class="comparison-table resort-comparison-table"><caption class="sr-only">مقارنة مواصفات ${selected.map(u=>safe(u.name)).join(' و')}</caption><thead><tr><th scope="col">المواصفات</th>${selected.map(u=>`<th scope="col"><img src="${safe(u.images[0])}" alt=""><strong>${safe(u.name)}</strong></th>`).join('')}</tr></thead><tbody>${rows.map(([title,read])=>`<tr><th scope="row">${title}</th>${selected.map(u=>`<td>${value(read(u))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">التفاصيل</th>${selected.map(u=>`<td>${link(u.path,'التفاصيل والصور','button outline')}</td>`).join('')}</tr></tbody></table></div>`;
}
function comparison(){
 if(route.venue==='resort')return resortComparison();
 const us=unitsFor('stay'),section=(u,pattern)=>u.sections.find(s=>pattern.test(s.title))?.items||[];
 const rows=[
  ['سعة الضيوف',u=>guests(u.guests)],
  ['زيادة العدد',u=>`حتى ${u.raw.maxGuests} ضيفًا برسوم إضافية`],
  ['غرف النوم',u=>rooms(u.rooms)],
  ['الأسرّة',u=>section(u,/^داخل/).filter(t=>/سرير|أسرّة|أسرة/.test(t))],
  ['المجلس',u=>section(u,/^داخل/).find(t=>/مجلس/.test(t))||'—'],
  ['الصالة الداخلية',u=>u.raw.hall?'متوفرة':'غير متوفرة'],
  ['الحمامات',u=>u.bathrooms+' حمامات'],
  ['مسبح الكبار',u=>section(u,/الخارجية/).find(t=>/مسبح خاص للكبار/.test(t))||'—'],
  ['مسبح الأطفال',u=>section(u,/الخارجية/).find(t=>/مسبح خاص للأطفال/.test(t))||'غير متوفر'],
  ['تجهيزات المطبخ',u=>section(u,/تجهيزات المطبخ/)],
  ['مميزات الإقامة',u=>section(u,/مميزات الإقامة/)],
  ['مرافق إضافية',u=>u.id===21?[...section(u,/الخارجية/).filter(t=>/ملعب/.test(t)),...u.description.split('\n').filter(t=>/زحليقة/.test(t))]:[]]
 ];
 const formatted=text=>safe(text).replace(/(\d+\s*×\s*\d+)/g,'<bdi dir="ltr">$1</bdi>');
 const value=text=>Array.isArray(text)?text.length?text.map(t=>`<span class="comparison-fact">${formatted(t)}</span>`).join(''):'—':formatted(text);
 return `<div class="stay-comparison">${heading('مقارنة قسمي الاستراحة')}<p class="note">قسمان مستقلان ولكل قسم مدخله ومرافقه الخاصة</p><div class="comparison-scroll" role="region" aria-label="مقارنة مواصفات قسمي الاستراحة" tabindex="0"><table class="comparison-table resort-comparison-table"><caption class="sr-only">مقارنة القسم الأول في الدور الأرضي والقسم الثاني في الدور العلوي</caption><thead><tr><th scope="col">المواصفات</th>${us.map(u=>`<th scope="col"><img src="${safe(u.images[0])}" alt=""><strong>${safe(u.name)}</strong></th>`).join('')}</tr></thead><tbody>${rows.map(([title,read])=>`<tr><th scope="row">${title}</th>${us.map(u=>`<td>${value(read(u))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">التفاصيل</th>${us.map(u=>`<td>${link(u.path,'التفاصيل والصور','button outline')}</td>`).join('')}</tr></tbody></table></div></div>`;
}

function resortMap(){return `<div class="tour-view map-original"><h1 class="resort-visual-title">خريطة الأكواخ التفاعلية</h1><iframe class="tour-frame" id="tour-frame" src="${ROOT}visuals/resort-map/${location.search}" title="خريطة الأكواخ التفاعلية" allow="clipboard-write; web-share; fullscreen" allowfullscreen></iframe></div>`;}
function tour(){const chalet=route.path==='/chalet-map/',title=chalet?'استكشف الشاليه من الداخل':'استكشف '+(explorationUnit()?.name||'مرافق الكوخ من الداخل');return `<div class="tour-view">${chalet?`<div class="sr-only"><h1>${safe(title)}</h1></div>`:`<h1 class="resort-visual-title">${safe(title)}</h1>`}<iframe class="tour-frame" id="tour-frame" src="${ROOT}visuals${route.path}${location.search}" title="${chalet?'خريطة الشاليه':'استكشاف الكوخ'}" allow="clipboard-write; web-share; fullscreen" allowfullscreen></iframe></div>`;}
function guide(){return `${heading('تجهيز مناسبتكم','نجهّز مناسباتكم بكل تفاصيلها')}<div class="services-list">${['coordination','dining','seating','hospitality','cinema'].map(id=>serviceCard(serviceBy(id))).join('')}</div>${link('/guest-services/',`<span>${icon('services')}خدمات إقامتك</span>${icon('arrow')}`,'explore-link')}`;}
function guestServices(){if(route.venue==='resort')return resortGuestGuide();return `${heading('خدمات إقامتك',venue().name)}<div class="services-list">${['water','games'].map(id=>serviceCard(serviceBy(id))).join('')}</div>`;}
function unavailable(){return `<div class="error-state"><h1>الصفحة غير موجودة</h1><p>اختر وجهتك للمتابعة</p>${link('/','الوجهات','button primary')}</div>`;}
function bindView(){const grid=$('.units-grid');if(grid)grid.addEventListener('scroll',()=>{const cards=[...grid.children],right=grid.getBoundingClientRect().right,i=cards.reduce((n,c,j)=>Math.abs(c.getBoundingClientRect().right-right)<Math.abs(cards[n].getBoundingClientRect().right-right)?j:n,0);if($('#carousel-count')){const resort=route.venue==='resort',cabins=resort?cards.filter(c=>c.dataset.unitId!=='11'):cards;$('#carousel-count').textContent=resort&&cards[i]?.dataset.unitId==='11'?'الحديقة المشتركة':`${i+1} / ${cabins.length}`;}},{passive:true});const search=$('#faq-search');if($('.faq-guide'))bindFaqGuide();else if(search)search.oninput=()=>{let count=0;document.querySelectorAll('[data-question]').forEach(e=>{e.hidden=!e.dataset.question.includes(search.value.trim());if(!e.hidden)count++;});$('#faq-empty').hidden=count>0;};const form=$('#checkout-form');if(form){form.addEventListener('submit',e=>{e.preventDefault();submitOrder(form);});form.addEventListener('input',()=>{const f=new FormData(form);state.customer={name:String(f.get('name')||''),cabin:String(f.get('cabin')||''),notes:String(f.get('notes')||'')};save();});}}
function rerenderSelection(){const opened=[...document.querySelectorAll('details[data-remember][open]')].map(e=>e.dataset.remember),top=scrollY;renderMain();opened.forEach(k=>{const e=[...document.querySelectorAll('details[data-remember]')].find(e=>e.dataset.remember===k);if(e)e.open=true;});window.scrollTo({top,behavior:'instant'});}
function changeQuantity(key,step){const s=route.service,d=draft(s?.id||'extras');let value,min=0,max=99,k=key;if(key==='qty'||key.startsWith('package:')||key.startsWith('session:')||key.startsWith('cakes:'))min=1;if(key.startsWith('package:'))k='package'+key.split(':')[1];if(key.startsWith('session:'))k='session'+key.split(':')[1];if(key.startsWith('cakes:')){const i=key.split(':')[1];k='cakes'+i;max=d['session'+i]||1;}if(key.startsWith('menu:'))k=key.slice(5);if(key.startsWith('extra:')){k=key.slice(6);min=1;}if(key==='packages'){min=1;max=20;}if(key==='adults')max=3*(d.packages||1)-(d.children||0);if(key==='children')max=3*(d.packages||1)-(d.adults||0);value=d[k]??min;d[k]=Math.max(min,Math.min(max,value+step));if(key==='packages'&&(d.adults||0)+(d.children||0)>3*d.packages){d.adults=0;d.children=0;}if(key.startsWith('session:')){const i=key.split(':')[1];d['cakes'+i]=Math.min(d['cakes'+i]||1,d[k]);}save();rerenderSelection();}
function showViewer(title,html){returnFocus=document.activeElement;$('#viewer-title').textContent=title;$('#viewer-body').innerHTML=html;$('[data-close]',viewer).innerHTML=icon('close');viewer.showModal();document.body.style.overflow='hidden';}
function showPhotos(images,labels,title,index=0){modalPhotos={images,labels,title,index};showViewer(title,lightboxMarkup());upgradeLightboxImage();}
function lightboxMarkup(){const m=modalPhotos;return `<img class="lightbox-image" src="${safe(route.venue==='resort'?displayServiceImage(m.images[m.index]):m.images[m.index])}" alt="${safe(m.labels?.[m.index]||m.title)}">${m.images.length>1?`<button class="gallery-control previous" data-modal-photo="-1" aria-label="الصورة السابقة">${icon('right')}</button><button class="gallery-control next" data-modal-photo="1" aria-label="الصورة التالية">${icon('left')}</button>`:''}<span class="lightbox-count">${m.index+1} / ${m.images.length}</span>`;}
function upgradeLightboxImage(){const target=$('.lightbox-image',viewer),original=modalPhotos?.images[modalPhotos.index];if(!target||!original||target.src===new URL(original,location.origin).href)return;const full=new Image();full.src=original;const ready=full.decode?full.decode():new Promise((resolve,reject)=>{full.onload=resolve;full.onerror=reject;});ready.then(()=>{if(target.isConnected&&modalPhotos?.images[modalPhotos.index]===original)target.src=original;}).catch(()=>{});}
function changePhoto(i){const u=currentUnit();if(!u)return;photoIndex=(i+u.images.length)%u.images.length;$('#gallery-image').src=u.images[photoIndex];$('#gallery-image').alt=u.labels[photoIndex]||u.name;$('#gallery-label').textContent=u.labels[photoIndex]||u.name;$('#gallery-count').textContent=`${photoIndex+1} / ${u.images.length}`;document.querySelectorAll('[data-thumbnail]').forEach((e,i)=>e.setAttribute('aria-pressed',String(photoIndex===i)));}
viewer.addEventListener('close',()=>{modalPhotos=null;$('#viewer-body').innerHTML='';document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});});
document.addEventListener('click',async e=>{
 const backLink=e.target.closest('a[data-history-back]');if(backLink&&!e.defaultPrevented&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();saveView();history.back();return;}
 const a=e.target.closest('a[href]');if(a&&!a.hasAttribute('data-service-portal')&&!e.defaultPrevented&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey&&e.button===0){const u=new URL(a.href,location.href);if(u.origin===location.origin&&u.pathname.startsWith(ROOT)&&!a.hasAttribute('download')){e.preventDefault();const section=a.hasAttribute('data-section-tab'),parent=a.hasAttribute('data-parent-back');const sibling=route.type==='unit'&&a.hasAttribute('data-cabin-switch');navigate(u.href,{section,parent,sibling,restore:section||parent});return;}}
 const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-share')){share(b.dataset.share,document.title);return;}
 if(b.hasAttribute('data-copy')){try{await navigator.clipboard.writeText(b.dataset.copy);toast('تم النسخ');}catch(_){toast(b.dataset.copy);}return;}
 if(b.hasAttribute('data-card-compare')){const id=Number(b.dataset.cardCompare);if(compare.has(id))compare.delete(id);else{if(compare.size>=3){toast('اختر حتى 3 أكواخ');return;}compare.add(id);}const selected=compare.has(id);b.setAttribute('aria-pressed',String(selected));b.setAttribute('aria-label',(selected?'إزالة ':'إضافة ')+unit(id).name+' '+(selected?'من المقارنة':'للمقارنة'));b.textContent=selected?'تم الاختيار':'قارن';}
 if(b.hasAttribute('data-filter')){filter=Number(b.dataset.filter);renderMain();}
 if(b.hasAttribute('data-carousel')){const g=$('.units-grid'),cards=[...g.children],right=g.getBoundingClientRect().right;let i=cards.reduce((n,c,j)=>Math.abs(c.getBoundingClientRect().right-right)<Math.abs(cards[n].getBoundingClientRect().right-right)?j:n,0);i=Math.max(0,Math.min(cards.length-1,i+Number(b.dataset.carousel)));cards[i].scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',inline:'start',block:'nearest'});}
 if(b.hasAttribute('data-photo'))changePhoto(photoIndex+Number(b.dataset.photo));
 if(b.hasAttribute('data-thumbnail'))changePhoto(Number(b.dataset.thumbnail));
 if(b.hasAttribute('data-lightbox-unit')){const u=currentUnit();showPhotos(u.images,u.labels,u.name,photoIndex);}
 if(b.hasAttribute('data-package-photo')){const image=b.dataset.packagePhoto,s=route.service;const p=s?.packages?.find(p=>p.images?.includes(image));showPhotos(p?.images||[image],[],p?.name||s?.name||'الصورة',p?.images?.indexOf(image)||0);}
 if(b.hasAttribute('data-modal-photo')&&modalPhotos){modalPhotos.index=(modalPhotos.index+Number(b.dataset.modalPhoto)+modalPhotos.images.length)%modalPhotos.images.length;$('#viewer-body').innerHTML=lightboxMarkup();upgradeLightboxImage();}
 if(b.hasAttribute('data-close'))viewer.close();
 if(b.hasAttribute('data-virtual'))showViewer('جولة ثلاثية الأبعاد للحديقة',`<iframe src="${safe(b.dataset.virtual)}" title="جولة الحديقة المشتركة" allow="fullscreen; xr-spatial-tracking" allowfullscreen></iframe>`);
 if(b.hasAttribute('data-qty'))changeQuantity(b.dataset.qty,Number(b.dataset.step));
 if(b.hasAttribute('data-dining-size')){draft('dining').size=b.dataset.diningSize;save();rerenderSelection();}
 if(b.hasAttribute('data-add'))addToCart(b.dataset.add);
 if(b.hasAttribute('data-remove')){state.cart=state.cart.filter(x=>entryKey(x)!==b.dataset.remove);save();renderMain();}

});
document.addEventListener('change',e=>{const t=e.target;if(t.hasAttribute('data-choice')){draft(route.service.id)[t.dataset.choice]=t.value;save();rerenderSelection();}if(t.hasAttribute('data-cheese')){draft('menu')['cheese:'+t.dataset.cheese]=t.checked;save();}if(t.hasAttribute('data-cake')){draft('seating')['cake'+t.dataset.cake]=t.checked;save();rerenderSelection();}if(t.hasAttribute('data-compare')){const id=Number(t.dataset.compare);if(t.checked){if(compare.size>=3){t.checked=false;toast('اختر حتى 3 أكواخ');return;}compare.add(id);}else compare.delete(id);if(route.type==='compare'){renderMain();$('[data-compare="'+id+'"]')?.focus({preventScroll:true});}}});
document.addEventListener('keydown',e=>{if(modalPhotos&&['ArrowLeft','ArrowRight'].includes(e.key)){modalPhotos.index=(modalPhotos.index+(e.key==='ArrowLeft'?1:-1)+modalPhotos.images.length)%modalPhotos.images.length;$('#viewer-body').innerHTML=lightboxMarkup();upgradeLightboxImage();}else if(!viewer.open&&currentUnit()&&e.target.closest('.gallery,.thumbnails')&&['ArrowLeft','ArrowRight'].includes(e.key))changePhoto(photoIndex+(e.key==='ArrowLeft'?1:-1));});
let touchX=0;main.addEventListener('touchstart',e=>{if(e.target.closest('.gallery'))touchX=e.touches[0].clientX;},{passive:true});main.addEventListener('touchend',e=>{if(e.target.closest('.gallery')&&Math.abs(e.changedTouches[0].clientX-touchX)>45)changePhoto(photoIndex+(e.changedTouches[0].clientX<touchX?1:-1));},{passive:true});
window.addEventListener('pagehide',()=>saveView());
window.addEventListener('popstate',()=>{saveView(activeEntryId);scrollPositions.set(previousURL,scrollY);render();restoreView();previousURL=location.href;});
window.addEventListener('message',e=>{const frame=$('#tour-frame');if(e.origin!==location.origin||!frame||e.source!==frame.contentWindow)return;if(e.data?.type==='familyday-preview-navigate'&&typeof e.data.path==='string'&&e.data.path.startsWith('/'))navigate(prefix(e.data.path));if(e.data?.type==='familyday-preview-virtual'&&e.data.url==='https://my.matterport.com/show/?m=S7Z2CF9tdwm')showViewer('جولة ثلاثية الأبعاد للحديقة',`<iframe src="${safe(e.data.url)}" title="جولة الحديقة المشتركة" allow="fullscreen; xr-spatial-tracking" allowfullscreen></iframe>`);if(e.data?.type==='familyday-preview-map-selection'&&route.type==='map'){const u=new URL(location.href);if(e.data.cabinId)u.searchParams.set('cabin',String(e.data.cabinId));else u.searchParams.delete('cabin');history.replaceState(history.state,'',u);previousURL=location.href;route.params=new URLSearchParams(u.search);const button=$('[data-share]');if(button)button.dataset.share=route.path+u.search;}});
try{const responses=await Promise.all([fetch(ROOT+'catalog.json?v='+VERSION),fetch(ROOT+'share-metadata.json?v='+VERSION),fetch(ROOT+'guide-copy.json?v='+VERSION),fetch(ROOT+'runtime-config.json?v='+VERSION)]);if(responses.some(response=>!response.ok))throw new Error('preview data');[catalog,shareMetadata,guideCopy,runtimeConfig]=await Promise.all(responses.map(response=>response.json()));state=readState();const old=legacyHash();if(old)history.replaceState(history.state,'',prefix(old));initEntry();render();}catch(e){main.innerHTML='<div class="error-state"><h1>تعذر تحميل المعاينة</h1><button class="button primary" onclick="location.reload()">إعادة المحاولة</button></div>';console.error(e);}

// Original service dialogs stay local; the normal Back button closes their top layer first.
document.addEventListener('click',e=>{if(legacyServiceLayer&&usesOriginalResortServices()&&e.target.closest('.context-back')){e.preventDefault();e.stopImmediatePropagation();$('#services-frame')?.contentWindow.postMessage({type:'familyday-preview-service-back'},location.origin);}},true);
window.addEventListener('message',e=>{const frame=$('#services-frame');if(e.origin!==location.origin||!frame||e.source!==frame.contentWindow)return;if(e.data?.type==='familyday-preview-service-layer'){legacyServiceLayer=String(e.data.layer||'');const label=$('.context-back>span:last-child');if(label){if(!label.dataset.serviceParent)label.dataset.serviceParent=label.textContent;label.textContent=legacyServiceLayer==='guide'?'تنسيقات وجلسات':legacyServiceLayer==='guest'?'خدمات إقامتك':legacyServiceLayer?route.service?.name||'الخدمة':label.dataset.serviceParent;}}if(e.data?.type==='familyday-preview-service-navigate'&&typeof e.data.path==='string'&&e.data.path.startsWith('/'))navigate(prefix(e.data.path));});
